      border-radius: 14px;
      cursor: pointer;
      font-weight: 800;
      transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.3);
      outline-offset: 3px;
    }

    .button-danger {
      color: #fff;
      background: var(--danger);
      box-shadow: 0 12px 24px rgba(223, 47, 69, 0.26);
    }

    .button-danger:hover {
      background: var(--danger-dark);
    }

    .button-secondary {
      color: var(--text);
      background: #eef2f8;
    }

    .button-primary {
      color: #fff;
      background: var(--primary);
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
    }

    .details-card {
      padding: 26px;
    }

    .details-card h2 {
      margin-bottom: 18px;
      font-size: 1.15rem;
      letter-spacing: -0.03em;
    }

    .metadata {
      display: grid;
      gap: 16px;
      margin: 0;
    }

    .metadata div {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding-bottom: 16px;
      border-bottom: 1px solid var(--line);
    }

    .metadata div:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .metadata dt {
      color: var(--muted);
      font-size: 0.88rem;
      font-weight: 700;
    }

    .metadata dd {
      margin: 0;
      font-weight: 800;
      text-align: right;
    }

    .modal-overlay {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      padding: 24px;
      background: rgba(12, 18, 32, 0.56);
      backdrop-filter: blur(10px);
      z-index: 10;
    }

    .modal-overlay.is-open {
      display: grid;
    }

    .modal {
      width: min(100%, 480px);
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.34);
      border-radius: 28px;
      background: var(--card);
      box-shadow: 0 40px 100px rgba(0, 0, 0, 0.32);
      animation: rise 180ms ease-out;
    }

    .modal-header {
      display: flex;
      align-items: flex-start;
      gap: 16px;
      padding: 28px 28px 18px;
    }

    .warning-icon {
      display: grid;
      flex: 0 0 46px;
      width: 46px;
      height: 46px;
      place-items: center;
      border-radius: 16px;
      color: var(--danger);
      background: #fff0f2;
      font-size: 1.35rem;
      font-weight: 900;
    }

    .modal h2 {
      margin-bottom: 8px;
      font-size: 1.55rem;
      letter-spacing: -0.05em;
    }

    .modal p {
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      padding: 22px 28px 28px;
      border-top: 1px solid var(--line);
    }

    .deleted-message {
      display: none;
      margin-top: 18px;
      padding: 14px 16px;
      border-radius: 16px;
      color: #0f5132;
      background: #dff7ea;
      font-weight: 800;
    }

    .deleted-message.is-visible {
      display: block;
    }

    @keyframes rise {
      from {
        opacity: 0;
        transform: translateY(14px) scale(0.98);
      }

      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @media (max-width: 860px) {
      .preview-layout {
        grid-template-columns: 1fr;
      }

      .topbar,
      .image-actions,
      .modal-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .modal-actions .button,
      .image-actions .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const image = {
      title: "Alpine Morning",
      description: "A high-resolution landscape from your saved inspiration library.",
      src: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80",
      alt: "A cabin beside a lake with mountains in the background",
      metadata: [
        ["Collection", "Travel"],
        ["Resolution", "3840 x 2400"],
        ["Uploaded", "May 5, 2026"],
        ["Storage", "12.8 MB"]
      ]
    };

    function Header() {
      return `
        <header class="topbar">
          <div class="brand" aria-label="Lumina Library">
            <span class="brand-mark">L</span>
            <span>Lumina</span>
          </div>
          <a class="library-link" href="#" aria-label="Back to image library">Back to library</a>
        </header>
      `;
    }

    function ImagePreview({ title, description, src, alt }) {
      return `
        <article class="image-card">
          <div class="image-frame">
            <img src="${src}" alt="${alt}">
            <span class="status-pill">Saved image</span>
          </div>
          <div class="image-actions">
            <div>
              <h1>${title}</h1>
              <p class="lede">${description}</p>
              <div class="deleted-message" id="deleted-message" role="status">
                Image deleted from your library.
              </div>
            </div>
            <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
              Delete image
            </button>
          </div>
        </article>
      `;
    }

    function DetailsPanel({ metadata }) {
      return `
        <aside class="details-card" aria-label="Image details">
          <h2>Image details</h2>
          <dl class="metadata">
            ${metadata.map(([label, value]) => `
              <div>
                <dt>${label}</dt>
                <dd>${value}</dd>
              </div>
            `).join("")}
          </dl>
        </aside>
      `;
    }

    function DeleteDialog({ title }) {
      return `
        <div class="modal-overlay" id="delete-dialog-overlay">
          <section
            class="modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="delete-dialog-title"
            aria-describedby="delete-dialog-description"
            tabindex="-1"
          >
            <div class="modal-header">
              <span class="warning-icon" aria-hidden="true">!</span>
              <div>
                <h2 id="delete-dialog-title">Delete this image?</h2>
                <p id="delete-dialog-description">
                  This will permanently remove "${title}" from your library. This action cannot be undone.
                </p>
              </div>
            </div>
            <div class="modal-actions">
              <button class="button button-secondary" type="button" data-close-dialog>Cancel</button>
              <button class="button button-danger" type="button" data-confirm-delete>Delete image</button>
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <main class="app-shell">
          ${Header()}
          <section class="preview-layout">
            ${ImagePreview(image)}
            ${DetailsPanel(image)}
          </section>
        </main>
        ${DeleteDialog(image)}
      `;
    }

    document.getElementById("root").innerHTML = App();

    const trigger = document.querySelector(".trigger");
    const overlay = document.getElementById("delete-dialog-overlay");
    const dialog = overlay.querySelector(".modal");
    const closeButtons = overlay.querySelectorAll("[data-close-dialog]");
    const confirmButton = overlay.querySelector("[data-confirm-delete]");
    const deletedMessage = document.getElementById("deleted-message");

    function openDialog() {
      overlay.classList.add("is-open");
      trigger.setAttribute("aria-expanded", "true");
      dialog.focus();
    }

    function closeDialog() {
      overlay.classList.remove("is-open");
      trigger.setAttribute("aria-expanded", "false");
      trigger.focus();
    }

    trigger.setAttribute("aria-expanded", "false");
    trigger.addEventListener("click", openDialog);

    closeButtons.forEach((button) => {
      button.addEventListener("click", closeDialog);
    });

    confirmButton.addEventListener("click", () => {
      closeDialog();
      deletedMessage.classList.add("is-visible");
      trigger.disabled = true;
      trigger.textContent = "Deleted";
    });

    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) {
        closeDialog();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && overlay.classList.contains("is-open")) {
        closeDialog();
      }
    });
  </script>
</body>
</html>
